### Phase 2: Autonomy-Aware Recovery Engine

#### 2.1 New Recovery Engine

**File:** `packages/daemon/src/lib/space/runtime/recovery-engine.ts` (NEW)

```typescript
/**
 * RecoveryEngine - Autonomy-aware task recovery with backoff
 */

export class RecoveryEngine {
  constructor(
    private config: RecoveryEngineConfig,
    private taskHealthMonitor: TaskHealthMonitor,
    private internalEventBus: InternalEventBus<DaemonInternalEventMap>,
    private taskAgentManager: TaskAgentManager,
  ) {}

  /**
   * Evaluate and execute recovery for a stuck/idle task
   */
  async recoverTask(
    healthState: TaskHealthState,
    autonomyLevel: SpaceAutonomyLevel
  ): Promise<RecoveryResult> {
    const strategy = this.selectRecoveryStrategy(healthState, autonomyLevel);

    switch (strategy.action) {
      case 'notify_only':
        return this.notifyOnly(healthState, strategy.reason);

      case 'nudge':
        return this.nudgeAgent(healthState, strategy.reason);

      case 'retry_with_backoff':
        return this.retryWithBackoff(healthState, strategy.reason);

      case 'restart':
        return this.restartAgent(healthState, strategy.reason);

      case 'escalate':
        return this.escalateToHuman(healthState, strategy.reason);

      case 'terminate':
        return this.terminateTask(healthState, strategy.reason);
    }
  }

  /**
   * Select recovery strategy based on autonomy level and task state
   */
  private selectRecoveryStrategy(
    state: TaskHealthState,
    autonomyLevel: SpaceAutonomyLevel
  ): RecoveryStrategy {
    const config = this.getAutonomyConfig(autonomyLevel);

    // Check retry limits first
    if (state.recoveryAttempts.length >= config.maxTotalRetries) {
      return { action: 'escalate', reason: 'Max total retries exceeded' };
    }

    if (state.consecutiveStuckCount >= config.maxConsecutiveRetries) {
      return { action: 'escalate', reason: 'Max consecutive retries exceeded' };
    }

    // Check wall-clock timeout
    const elapsed = Date.now() - state.lastWorkflowTransitionAt;
    if (elapsed > config.workflowTimeoutMs) {
      return autonomyLevel >= 3
        ? { action: 'escalate', reason: 'Workflow timeout exceeded' }
        : { action: 'notify_only', reason: 'Workflow timeout at low autonomy' };
    }

    // Stuck detection with progressive recovery
    if (state.consecutiveIdleCount >= 3) {
      if (autonomyLevel <= 2) {
        return { action: 'notify_only', reason: 'Repeated idle at low autonomy' };
      }

      if (state.recoveryAttempts.filter(a => a.strategy === 'nudge').length < config.maxNudges) {
        return { action: 'nudge', reason: 'Agent idle - attempting nudge' };
      }

      if (state.recoveryAttempts.filter(a => a.strategy === 'restart').length < config.maxRestarts) {
        return { action: 'restart', reason: 'Nudge failed - attempting restart' };
      }

      return { action: 'escalate', reason: 'Nudge and restart exhausted' };
    }

    // Default: notify only if under threshold
    return { action: 'notify_only', reason: 'Monitoring - under threshold' };
  }

  /**
   * Exponential backoff with jitter for retries
   */
  private calculateBackoffMs(
    attemptNumber: number,
    baseDelayMs: number = 5000
  ): number {
    const exponentialMs = baseDelayMs * Math.pow(2, attemptNumber);
    const jitterMs = Math.random() * 0.1 * exponentialMs; // ±10% jitter
    return Math.min(exponentialMs + jitterMs, 300_000); // Max 5 minutes
  }

  /**
   * Rate-limited notification check
   */
  private shouldNotify(state: TaskHealthState): boolean {
    const lastNotification = state.recoveryAttempts
      .filter(a => a.strategy === 'notify')
      .pop();

    if (!lastNotification) return true;

    const elapsed = Date.now() - lastNotification.timestamp;
    return elapsed >= this.config.minNotificationIntervalMs;
  }
}
```

