### Phase 3: Reduced Event Noise

#### 3.1 Notification Filtering

**File:** `packages/daemon/src/lib/space/runtime/notification-filter.ts` (NEW)

```typescript
/**
 * NotificationFilter - Reduce noise by filtering and rate-limiting events
 */

export class NotificationFilter {
  private recentNotifications = new Map<string, number>();
  private suppressedCount = new Map<string, number>();

  /**
   * Check if notification should be emitted
   */
  shouldNotify(
    kind: string,
    spaceId: string,
    taskId: string,
    payload: Record<string, unknown>
  ): { emit: boolean; reason?: string } {
    const key = `${kind}:${spaceId}:${taskId}`;

    // Filter out successful completions (unless audit mode)
    if (kind === 'workflow_run_completed' && payload.status === 'done') {
      const auditMode = this.isAuditMode(spaceId);
      if (!auditMode) {
        this.suppressedCount.set(key, (this.suppressedCount.get(key) ?? 0) + 1);
        return { 
          emit: false, 
          reason: 'Successful completion in normal mode' 
        };
      }
    }

    // Rate limiting for stuck/idle notifications
    if (this.isStuckEvent(kind)) {
      const lastNotified = this.recentNotifications.get(key) ?? 0;
      const elapsed = Date.now() - lastNotified;

      if (elapsed < this.config.minNotificationIntervalMs) {
        return { 
          emit: false, 
          reason: `Rate limited (${Math.round(elapsed / 1000)}s since last)` 
        };
      }
    }

    // Only notify for actionable events
    if (!this.isActionable(kind, payload)) {
      return { emit: false, reason: 'Not actionable' };
    }

    this.recentNotifications.set(key, Date.now());
    return { emit: true };
  }

  /**
   * Check if event is actionable (requires human/agent intervention)
   */
  private isActionable(kind: string, payload: Record<string, unknown>): boolean {
    const actionableKinds = [
      'task_blocked',
      'workflow_run_blocked', 
      'task_timeout',
      'workflow_run_needs_attention',
      'agent_crash',
    ];

    // task_retry events are only actionable if approaching limits
    if (kind === 'task_retry') {
      const attempt = payload.attemptNumber as number;
      const max = payload.maxAttempts as number;
      return attempt >= max - 1;
    }

    return actionableKinds.includes(kind);
  }

  /**
   * Get suppression statistics for monitoring
   */
  getSuppressionStats(): Map<string, number> {
    return new Map(this.suppressedCount);
  }
}
```

