private async executeTick(): Promise<void> {
  // ... existing setup ...

  // NEW: Comprehensive health check
  await this.checkAllTaskHealth();

  // ... existing tick logic ...
}

private async checkAllTaskHealth(): Promise<void> {
  const spaces = await this.listActiveSpaces();

  for (const space of spaces) {
    const runs = this.workflowRunRepo.listBySpace(space.id, 'in_progress');

    for (const run of runs) {
      const executions = this.nodeExecutionRepo.listByWorkflowRun(run.id);
      const autonomyLevel = space.autonomyLevel ?? 1;

      for (const execution of executions) {
        const health = await this.taskHealthMonitor.checkTaskHealth(
          run, execution, space
        );

        if (health.status === 'stuck' || health.status === 'idle') {
          await this.recoveryEngine.recoverTask(health, autonomyLevel);
        }
      }
    }
  }
}
```

3. **Filtered event emission:**
```typescript
private async safeNotify(event: DaemonInternalEventMap[keyof DaemonInternalEventMap]): Promise<void> {
  // Extract kind and identifiers
  const kind = event.kind;
  const spaceId = event.spaceId;
  const taskId = 'taskId' in event ? event.taskId : event.runId;

  // Check filter
  const { emit, reason } = this.notificationFilter.shouldNotify(
    kind, spaceId, taskId, event as Record<string, unknown>
  );

  if (!emit) {
    log.debug(`Notification suppressed: ${reason}`);
    return;
  }

  // Log suppressed events for debugging
  if (reason) {
    log.debug(`Notification allowed: ${reason}`);
  }

  // Emit event
  await this.internalEventBus.publishAsync(event);
}
```

